    l = int(parts[0])
    r = int(parts[1])

    # Miller-Rabin primality test
    def power(base, exp, mod):
        result = 1
        base %= mod
        while exp > 0:
            if exp % 2 == 1:
                result = (result * base) % mod
            base = (base * base) % mod
            exp //= 2
        return result

    def miller_rabin(n):
        if n < 2:
            return False
        if n == 2 or n == 3:
            return True
        if n % 2 == 0:
            return False

        # Write n-1 as 2^r * d
        r = 0
        d = n - 1
        while d % 2 == 0:
            r += 1
            d //= 2

        # Bases for deterministic Miller-Rabin up to various ranges
        if n < 4759123141:
            bases = [2, 7, 61]
        else:
            bases = [2, 3, 5, 7, 11, 13, 17, 19, 23]

        for a in bases:
            if n <= a:
                break
            x = power(a, d, n)
            if x == 1 or x == n - 1:
                continue
            for _ in range(r - 1):
                x = (x * x) % n
                if x == n - 1:
                    break
            else:
                return False
        return True

    # Count primes in [l, r] that are either 2 or ≡ 1 (mod 4)
    # A prime can be written as sum of two positive squares iff p=2 or p≡1 (mod 4)
    count = 0
    for i in range(l, r + 1):
        if i >= 2 and miller_rabin(i):
            if i == 2 or i % 4 == 1:
                count += 1

    return str(count) + '\n'
