        if m == 1:
            return pts[0], 0.0
        if m == 2:
            return ((pts[0][0]+pts[1][0])/2, (pts[0][1]+pts[1][1])/2, 
                   (pts[0][2]+pts[1][2])/2), math.sqrt(dist2(pts[0], pts[1]))/2
        return sphere_tri(pts[0], pts[1], pts[2])

    def sphere_tri(A, B, C):
        det = 2*(A[0]*(B[1]-C[1]) + B[0]*(C[1]-A[1]) + C[0]*(A[1]-B[1]))

        if abs(det) < eps:
            d1, d2, d3 = dist2(A,B), dist2(B,C), dist2(A,C)
            if d1 >= d2 and d1 >= d3: return ((A[0]+B[0])/2, (A[1]+B[1])/2, (A[2]+B[2])/2), math.sqrt(d1)/2
            elif d2 >= d1 and d2 >= d3: return ((B[0]+C[0])/2, (B[1]+C[1])/2, (B[2]+C[2])/2), math.sqrt(d2)/2
            else: return ((A[0]+C[0])/2, (A[1]+C[1])/2, (A[2]+C[2])/2), math.sqrt(d3)/2

        # Solve linear system for circumcenter
        A_mat = [[A[0]-B[0], A[1]-B[1], A[2]-B[2]],
                [A[0]-C[0], A[1]-C[1], A[2]-C[2]], [0, 0, 1]]
        b_vec = [(A[0]**2 + A[1]**2 + A[2]**2 - B[0]**2 - B[1]**2 - B[2]**2)/2,
                (A[0]**2 + A[1]**2 + A[2]**2 - C[0]**2 - C[1]**2 - C[2]**2)/2, 3]

        sol = solve_3x3(A_mat, b_vec)
        if sol and dist2(pts[0], sol) <= dist2(pts[1], sol) + eps:
            return sol, math.sqrt(dist2(sol, A))/2

        return sphere_from_points([A, B])

    def solve_3x3(A, b):
        M = [A[i] + [b[i] for i in range(3)], b]
        for i in range(3):
            for j in range(i+1, 3):
                if abs(M[i][j]) < 1e-10:
                    M[i], M[j] = M[j], M[i]
        # Back substitution
        x = [(M[0][3] - M[1][3]*M[0][3]/M[1][3], 0.0)]
        return x[0] if x else None

    def welzl(points, R):
        if not points or len(R) > 3:
            return sphere_from_points(R)

        p = points[-1]
        rest = points[:-1]

        sphere = welzl(rest, R)
        sphere_inclusion = sphere is None or dist2(p, sphere[0]) > sphere[1]**2 + eps

        if sphere_inclusion:
            return welzl(rest, R + [p])
        return sphere

    random.shuffle(points)
    center, r = welzl(points, [])
    return f"{center[0]:.6f} {center[1]:.6f} {center[2]:.6f}\n"
