            limit = int(s[pos]) if not is_less else 9
            result = 0

            for d in range(limit + 1):
                new_less = is_less or (d < limit)
                # For each position, count contributions
                remaining = n_len - pos - 1
                if remaining >= 0:
                    # This digit d appears in all suffixes
                    result += d * (10 ** remaining)
                    result += dp(pos + 1, new_less)

