                count = power * limit + (n % power)
                total += d * count

            # Handle the actual digit
            # Remaining part contributes
            total += digit_sum(n)  # Add final number's digit sum

        # Correct calculation - straightforward but works for reasonable ranges
        return sum(digit_sum(x) for x in range(n + 1))

    # Search for valid l and r
    limit_small = min(a * 1000000, 10000000)

    for l in range(1, limit_small + 1):
        end_r = min(l + 1000000, limit_small + a * 1000000)
        for r in range(l, end_r + 1):
