```python
from collections import deque, defaultdict

def solution(input_str):
    """
    Solves the tree transformation problem to convert to a star graph.

    The key insight is that the minimum operations needed equals the tree's
    diameter minus 1. If the tree is already a star (one node connected to
    all others), no operations are needed.
    """
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    # Handle edge case
    if n < 3:
        return '0\n'

    # Build adjacency list
    adj = defaultdict(list)
    for i in range(1, n):
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)

    # Check if already a star (one node with degree n-1)
    for v in range(1, n + 1):
        if len(adj[v]) == n - 1:
            return '0\n'

    # BFS to compute maximum distance from a starting node
    def bfs(start):
        dist = {start: 0}
        queue = deque([start])
        while queue:
            node = queue.popleft()
            for neighbor in adj[node]:
                if neighbor not in dist:
                    dist[neighbor] = dist[node] + 1
                    queue.append(neighbor)
        return max(dist.values())

    # Compute tree diameter (longest path in tree)
    diameter = 0
    for start in range(1, n + 1):
        diameter = max(diameter, bfs(start))

    # Answer is diameter - 1
    return str(diameter - 1) + '\n'
