import os

def solution(s):
    n = int(s.strip())

    if n <= 0:
        return "0\n"

    # Memoization-based DFS with pruning
    memo = {}

    def solve(num):
        if num == 0:
            return 0
        if num in memo:
            return memo[num]

        digits = set(int(d) for d in str(num))

        # Greedy: always subtract largest digit first for efficiency
        best = float('inf')
        for d in digits:
            if num - d in memo:
                best = min(best, memo[num - d] + 1)
            else:
                result = solve(num - d)
                if result != -1:
                    best = min(best, result + 1)

        memo[num] = best if best != float('inf') else -1
        return best

    ans = solve(n)
    return str(ans) + "\n" if ans != -1 else str(-1) + "\n"
