            count = 0
            for i in range(1, int(n**0.5) + 1):
                if n % i == 0:
                    count += 1
                    if i * i != n:
                        count += 1
            return count

        def matrix_multiply(A, B, n, mod):
            C = [[0] * n for _ in range(n)]
            for i in range(n):
                for k in range(n):
                    if A[i][k] == 0:
                        continue
                    for j in range(n):
                        if B[k][j] != 0:
                            C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % mod
            return C

