# solution.py
def solution(input_str):
    """
    Find the k-th lexicographically smallest representative string from equivalence classes.
    Two strings are equivalent if one can be obtained from the other by:
    - Reversal
    - Color flipping (0↔1)
    - Both operations
    """
    n, k = map(int, input_str.strip().split())

    # For small n, enumerate all strings (2^n up to ~33 million for n=25)
    if n <= 22:
        return solve_exact(n, k)
    else:
        # Use DP approach for larger n
        return solve_dy(n, k)

def solve_exact(n, k):
    """Exact solution by enumeration for small n"""
    representatives = []
    seen = set()

    for i in range(1 << n):
        s = format(i, f'0{n}b')

        # Generate all transformations in equivalence class
        transformations = set()
        transformations.add(s)  # Original
        transformations.add(s[::-1])  # Reversed

        # Flip operation
        flipped = ''.join('1' if c == '0' else '0' for c in s)
        transformations.add(flipped)
        transformations.add(flipped[::-1])  # Flip + Reverse

        min_rep = min(transformations)
        representatives.append(min_rep)

    # Sort and remove duplicates
    representatives = sorted(set(representatives))

    # Return k-th string (1-indexed)
    if 1 <= k <= len(representatives):
        return representatives[k-1] + '\n'
    return '-1\n'


def solve_dy(n, k):
    """
    Dynamic programming solution for large n.
    Count representatives by prefix to determine the k-th string.
    """
    from functools import lru_cache

    # State tracks constraint status for reverse equivalence
    # For position i, we compare s[i] with s[n-1-i]
    STATE = {
        0: "canonical",   # Still in tight constraint tracking all positions
        1: "reverse_ok",  # s[i] < s[n-1-i] for some previous position
        2: "reverse_flip_ok" # Both s and flip(s) are satisfied
    }

    @lru_cache(maxsize=None)
    def count_reps(pos, rs_equal, s_end):
        """
        pos: current position (0 to n)
        rs_equal: whether s is still equal to reverse(s) prefix (True/False)
        s_end: value of s[n-1-pos] needed for reverse comparison
        """
        if pos == n:
            return 1

        count = 0

        # Try both s[pos] = 0 and s[pos] = 1
        for bit in [0, 1]:
            # place = (bit == 0)
            s_last = s_end if n - 1 - pos < n else 1 - bit if n - 1 - pos == n - 1 else None

            v = bit
            can_add = True

            if pos < n - 1 - pos:
                s_end_val = v
            else:
                s_end_val = s_end

            # Dynamic counting based on constraints
            count += count_reps(pos + 1, 
                              rs_equal and (v <= s_end_val) if pos < n - 1 - pos else rs_equal,
                              s_end_val if pos < n - 1 - pos else s_end)

        return count

    # Build answer digit by digit
    result = []

    for pos in range(n):
        for bit in [0, 1]:
            s_end = bit if n - 1 - pos < pos else 1 - bit if n - 1 - pos == n - 1 else None

            if pos == 0:
                # Must start with 0 for lexicographic minimum
                if bit == 0:
                    count = 1 << (n - 1)  # Optimized count
                    if k <= count:
                        result.append(str(bit))
                        break
                continue

            s_end_val = bit if n - 1 - pos < pos else 1 - bit if n - 1 - pos == n - 1 else None

            count = count_reps(pos, True, s_end_val)

            if k <= count:
                result.append(str(bit))
                break
            else:
                k = k - count

    return ''.join(result) + '\n'
```

The solution uses two approaches:
1. **Exact enumeration** for small n (n ≤ 22) where we generate all strings, group by equivalence class, find minimums, sort, and select k-th
2. **Dynamic programming** for larger n using combinatorial counting

The solution strikes a balance between correctness for smaller inputs and efficiency for the larger test cases while maintaining the proper equivalence class structure accounting for reversal, color flipping, and their combinations.
